/* coral-biodiversity — scroll is time: engraving line first, then
   hand-colour washes flood in wet-on-wet. Final frame is the plate itself. */
export function coralBiodiversity(runway, opts = {}) {
  const frame = runway.querySelector('.cb-frame');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  let raf = 0, target = 0, current = reduced ? 1 : 0, visible = true, destroyed = false;
  const clamp01 = v => Math.min(1, Math.max(0, v));
  function measure() {
    const r = runway.getBoundingClientRect();
    const total = runway.offsetHeight - innerHeight;
    target = total > 0 ? clamp01(-r.top / total) : 1;
  }
  function apply() {
    frame.style.setProperty('--p', current.toFixed(4));
    frame.style.setProperty('--wet', (4 * current * (1 - current)).toFixed(4));
  }
  let vel = 0;
  function tick() {
    raf = 0;
    const w = target > current ? 10 : 15;
    const dt = 1 / 60;
    vel += (-w * w * (current - target) - 2 * w * vel) * dt;
    current = clamp01(current + vel * dt);
    if (Math.abs(target - current) < 0.0004 && Math.abs(vel) < 0.0004) { current = target; vel = 0; apply(); return; }
    apply();
    if (visible && !document.hidden && !destroyed) raf = requestAnimationFrame(tick);
  }
  function kick() { measure(); if (!raf && visible && !destroyed) raf = requestAnimationFrame(tick); }
  const onScroll = () => kick(), onResize = () => kick();
  addEventListener('scroll', onScroll, { passive: true });
  addEventListener('resize', onResize);
  const io = new IntersectionObserver(e => { visible = e[0].isIntersecting; if (visible) kick(); else if (raf) { cancelAnimationFrame(raf); raf = 0; } });
  io.observe(runway);
  if (reduced) { current = target = 1; apply(); }
  else kick();
  return function destroy() {
    destroyed = true;
    if (raf) cancelAnimationFrame(raf);
    removeEventListener('scroll', onScroll); removeEventListener('resize', onResize);
    io.disconnect();
    frame.style.removeProperty('--p'); frame.style.removeProperty('--wet');
  };
}
let api = null;
const el = document.querySelector('[data-coral-biodiversity]');
if (el) api = coralBiodiversity(el);
export function destroy() { if (api) { api(); api = null; } }
if (typeof window !== 'undefined') window.__coralBiodiversity = { destroy };

/* coral-biodiversity — colour and light build over Haeckel's Actiniae plate. */
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:#f3efe3;overflow-x:hidden}
.cb-runway{height:370vh;position:relative}
.cb-stage{position:sticky;top:0;height:100svh;display:grid;place-items:center;background:#f3efe3;overflow:hidden}
.cb-frame{position:relative;height:min(94svh,1180px);aspect-ratio:1824/2560;max-width:94vw;touch-action:pan-y}
.cb-frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;user-select:none;-webkit-user-drag:none}
.cb-base{filter:grayscale(.92) contrast(1.1) brightness(1.08) sepia(.16)}
.cb-top{
  -webkit-mask-image:linear-gradient(to top,#000 calc(var(--p,0)*118%),transparent calc(var(--p,0)*118% + 14%));
  mask-image:linear-gradient(to top,#000 calc(var(--p,0)*118%),transparent calc(var(--p,0)*118% + 14%))}
.cb-caustics{position:absolute;inset:0;pointer-events:none;mix-blend-mode:overlay;opacity:var(--wet,0);
  background:
    radial-gradient(38% 22% at calc(28% + var(--p,0)*9%) 18%,rgba(255,255,240,.85),transparent 70%),
    radial-gradient(30% 18% at calc(68% - var(--p,0)*7%) 30%,rgba(210,240,255,.7),transparent 70%),
    radial-gradient(45% 26% at 50% calc(58% - var(--p,0)*6%),rgba(255,248,215,.55),transparent 72%);
  background-color:transparent}
@media (prefers-reduced-motion: reduce){
  .cb-runway{height:auto}
  .cb-stage{position:static;height:auto;padding:4svh 0}
  .cb-top{-webkit-mask-image:none;mask-image:none}
  .cb-caustics{opacity:0}
}

